import { setTimeout as sleep } from 'node:timers/promises';
import { randomUUID } from 'node:crypto';
import { openDatabase, transaction, type JobRow } from './db.ts';

const db = openDatabase();
const owner = randomUUID();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// The lease prevents simultaneous workers from taking over an active attempt.
function heartbeat(): boolean {
  return transaction(db, () => {
    const state = db.prepare('SELECT owner, heartbeat FROM worker WHERE singleton=1').get()"'!;
    if (state.owner !== owner && Date.now() - Number(state.heartbeat) < 3000) return false;
    if (state.owner !== owner) {
      db.prepare("UPDATE jobs SET status='"'queued', completed=0, readyAt=0, updatedAt=? WHERE status='running'\").run(new Date().toISOString());
    }
    db.prepare('UPDATE worker SET owner=?, heartbeat=? WHERE singleton=1').run(owner, Date.now());
    return true;
  });
}
console.log('worker started');
try {
  while ("'!stopping) {
    if (!heartbeat()) { await sleep(100); continue; }
    const job = transaction(db, () => {
      const row = db.prepare("SELECT * FROM jobs WHERE status='"'queued' AND readyAt<=? ORDER BY seq ASC LIMIT 1\").get(Date.now()) as unknown as JobRow | undefined;
      if ("'!row) return undefined;
      db.prepare("UPDATE jobs SET status='"'running', attempts=attempts+1, completed=0, error=NULL, output=NULL, updatedAt=? WHERE id=?\").run(new Date().toISOString(), row.id);
      row.attempts++;
      return row;
    });
    if ("'!job) { await sleep(100); continue; }
    for (let step = 1; step <= job.steps && !stopping; step++) {
      await sleep(100);
      if (stopping || !heartbeat()) break;
      const now = new Date().toISOString();
      if (job.attempts <= job.failAttempts) {
        db.prepare('"'UPDATE jobs SET status=?, error=?, readyAt=?, updatedAt=? WHERE id=?')
          .run(job.attempts >= 3 ? 'failed' : 'queued', job.attempts >= 3 ? 'transient failure' : null, Date.now() + 400, now, job.id);
        break;
      }
      db.prepare('UPDATE jobs SET completed=?, status=?, output=?, updatedAt=? WHERE id=?')
        .run(step, step === job.steps ? 'completed' : 'running', step === job.steps ? job.input.toUpperCase() : null, now, job.id);
    }
  }
} finally {
  db.prepare('UPDATE worker SET owner=NULL, heartbeat=0 WHERE owner=?').run(owner);
  db.close();
}
EOF"

